"use client";
import { CardImageSection } from "./card-image-section";
import data from "./data.json";

export default function Page() {
  return <CardImageSection data={data} />;
}

import { ArrowPointer, Button } from "../../ui/button/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardImage,
  CardTitle,
} from "../../ui/card/card";

type CardData = {
  id: number;
  imageSrc: string;
  alt: string;
  title: string;
  description: string;
  href?: string;
};

type CardImageSectionProps = {
  data: {
    caption: string;
    heading: string;
    description: string;
    cards: CardData[];
  };
};

export function CardImageSection({ data }: CardImageSectionProps) {
  return (
    <section className="mx-auto w-full max-w-[900px] px-6 py-12 max-sm:px-4 max-sm:py-8">
      <header className="mb-12 text-left max-sm:mb-8">
        <span className="mb-3 block font-medium text-[length:var(--font-size-sm)] text-[var(--accent)] uppercase tracking-[0.05em]">
          {data.caption}
        </span>
        <h2 className="m-0 mb-4 font-semibold text-[clamp(1.75rem,4vw,2.5rem)] text-[var(--foreground)] leading-[1.2] tracking-[-0.02em]">
          {data.heading}
        </h2>
        <p className="m-0 max-w-[600px] text-[var(--muted-foreground)] text-base leading-[1.6]">{data.description}</p>
      </header>

      <div className="columns-1 sm:columns-2 sm:gap-x-6">
        {data.cards.map((card, index) => (
          <Card
            className={`mb-6 max-w-full break-inside-avoid rounded-[16px] [transform:translateZ(0)] sm:rounded-[20px] ${index === 0 ? "sm:mt-[120px]" : ""}`}
            key={card.id}
            variant="lift"
          >
            <CardImage alt={card.alt} className="w-auto rounded-[8px] sm:rounded-[12px]" src={card.imageSrc} />

            <CardContent className="gap-2">
              <CardTitle className="m-0 max-sm:text-[1.125rem] max-sm:leading-[1.3]">{card.title}</CardTitle>
              <CardDescription className="mt-0">{card.description}</CardDescription>
            </CardContent>

            <CardFooter>
              <Button
                className="pl-0"
                nativeButton={false}
                render={
                  // biome-ignore lint/a11y/useAnchorContent: link text is passed as Button children
                  <a href={card.href ?? "#"} />
                }
                size="sm"
                variant="link"
              >
                Learn More
                <ArrowPointer />
              </Button>
            </CardFooter>
          </Card>
        ))}
      </div>
    </section>
  );
}

{
  "caption": "What you get",
  "heading": "Four reasons to use Roi UI",
  "description": "Each component is ready to use, easy to change, and works for everyone.",
  "cards": [
    {
      "id": 1,
      "imageSrc": "/arch-01.webp",
      "alt": "Stone arches and cypress trees under a night sky with a crescent moon",
      "title": "Accessible by default",
      "description": "Every component works with a keyboard and a screen reader. You do not need extra setup."
    },
    {
      "id": 2,
      "imageSrc": "/arch-02.webp",
      "alt": "A white city of temples and gardens under a bright blue sky",
      "title": "You own the code",
      "description": "You copy the source into your project. You can change any part of it."
    },
    {
      "id": 3,
      "imageSrc": "/arch-03.webp",
      "alt": "Stone columns and terraces covered in cypress trees and flowers",
      "title": "Two ways to style",
      "description": "Choose CSS Modules or Tailwind. Both versions look and work the same."
    },
    {
      "id": 4,
      "imageSrc": "/arch-04.webp",
      "alt": "White stone arches rising over a green forest pond under a blue sky",
      "title": "Motion with a purpose",
      "description": "Animations show what changed and where to look. They stay small, so they never slow you down."
    }
  ]
}
